[{"id": "bdbf415", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}}, "elements": [{"id": "ea8e502", "elType": "widget", "settings": {"html": "<section class="sdi-page-header"><div class="sdi-container sdi-page-header__inner"><p class="sdi-page-header__crumb"><a href="/">Home</a> / Programs</p><p class="sdi-page-header__eyebrow">Five member programs</p><h1 class="sdi-page-header__title">Programs</h1><p class="sdi-page-header__subhead">Five member programs. Each one states its purpose, who is eligible, how to take part, and the terms that govern it.</p></div></section>"}, "elements": [], "isInner": false, "widgetType": "html"}], "isInner": false}, {"id": "4a00354", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-section sdi-section--light"}, "elements": [{"id": "0ded45d", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-container", "flex_direction": "column", "flex_gap": {"unit": "px", "size": 32, "column": "32", "row": "32"}}, "elements": [{"id": "a57119c", "elType": "widget", "settings": {"html": "<div class="sdi-program-index"><a class="sdi-program-index__item" href="#referral"><p class="sdi-numbered-card__number">01</p><p class="sdi-program-index__title">Member Referral Program</p><p class="sdi-program-index__note">On this page</p></a><a class="sdi-program-index__item" href="/fundraising/"><p class="sdi-numbered-card__number">02</p><p class="sdi-program-index__title">Travel Purchase Fundraising</p><p class="sdi-program-index__note">Full page</p></a><a class="sdi-program-index__item" href="/partnerships/"><p class="sdi-numbered-card__number">03</p><p class="sdi-program-index__title">Retailer &amp; Restaurant Partnerships</p><p class="sdi-program-index__note">Full page</p></a><a class="sdi-program-index__item" href="/scholarships/"><p class="sdi-numbered-card__number">04</p><p class="sdi-program-index__title">Academic Scholarship Program</p><p class="sdi-program-index__note">Full page</p></a><a class="sdi-program-index__item" href="#community"><p class="sdi-numbered-card__number">05</p><p class="sdi-program-index__title">Community Engagement</p><p class="sdi-program-index__note">On this page</p></a></div>"}, "elements": [], "isInner": false, "widgetType": "html"}], "isInner": true}], "isInner": false}, {"id": "a0c2f2f", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "_element_id": "referral", "css_classes": "sdi-section sdi-section--light"}, "elements": [{"id": "fa1ab02", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-container", "flex_direction": "column", "flex_gap": {"unit": "px", "size": 32, "column": "32", "row": "32"}}, "elements": [{"id": "01b339a", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-grid sdi-grid--2", "flex_gap": {"unit": "px", "size": 48, "column": "48", "row": "48"}}, "elements": [{"id": "902d56f", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "flex_direction": "column", "flex_gap": {"unit": "px", "size": 14, "column": "14", "row": "14"}}, "elements": [{"id": "6e51a5f", "elType": "widget", "settings": {"editor": "<p style='font-family:ui-monospace,Menlo,monospace;font-size:0.75rem;color:var(--sdi-color-silver);'>Program 01 · runs on this page</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}, {"id": "9e7b2d7", "elType": "widget", "settings": {"title": "Member Referral Program", "header_size": "h2"}, "elements": [], "isInner": false, "widgetType": "heading"}, {"id": "abbb8a2", "elType": "widget", "settings": {"editor": "<p style='color:#2c3a51;max-width:52ch;'>Each member gets a personal referral link. When someone you refer completes a paid membership, you earn points that move you up the published scholarship award ladder.</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}, {"id": "a79a902", "elType": "widget", "settings": {"text": "Estimate your tier", "link": {"url": "#calculator", "is_external": "", "nofollow": ""}, "css_classes": "sdi-btn sdi-btn--primary"}, "elements": [], "isInner": false, "widgetType": "button"}], "isInner": true}, {"id": "a6b5c48", "elType": "widget", "settings": {"html": "<div class="sdi-fact-grid"><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Purpose</p><p>Grow the member community while funding scholarships — referrals are the single largest source of new scholarship dollars.</p></div><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Eligibility</p><p>Active members in good standing, Individual or Family. Family households share one combined points balance.</p></div><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Participation process</p><p>Share your referral link from the Member Portal. You earn 30 points per eligible referral, confirmed once the new member completes a paid membership within 60 days.</p></div><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Applicable terms</p><p>Points do not expire while membership remains active and are forfeited after a 90-day lapse. Awards are subject to program rules, available funding, verification and applicable law.</p><a href="/legal/#referral-rules" class="sdi-auth-link">Referral Program Rules</a></div></div>"}, "elements": [], "isInner": false, "widgetType": "html"}], "isInner": true}], "isInner": true}], "isInner": false}, {"id": "29d1b83", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "_element_id": "calculator", "css_classes": "sdi-section sdi-section--navy"}, "elements": [{"id": "12986eb", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-container", "flex_direction": "column", "flex_gap": {"unit": "px", "size": 32, "column": "32", "row": "32"}}, "elements": [{"id": "9d2a1f0", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "flex_direction": "column", "flex_gap": {"unit": "px", "size": 16, "column": "16", "row": "16"}}, "elements": [{"id": "8365e91", "elType": "widget", "settings": {"title": "Estimate your scholarship tier", "header_size": "h2"}, "elements": [], "isInner": false, "widgetType": "heading"}, {"id": "fbd9f2c", "elType": "widget", "settings": {"editor": "<p style='color:#DCDEE3;max-width:48ch;'>Enter how many referrals you expect to confirm. Thirty points each; four published tiers.</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}, {"id": "077c847", "elType": "widget", "settings": {"html": "
    <div class="sdi-calculator">
      <label class="sdi-calculator__label">Confirmed referrals
        <input type="number" min="0" max="200" value="0" id="sdi-calc-input" class="sdi-calculator__input" />
      </label>
      <input type="range" min="0" max="60" step="1" value="0" id="sdi-calc-range" aria-label="Confirmed referrals slider" class="sdi-calculator__range" />
      <div class="sdi-calculator__readout">
        <div><span class="sdi-calculator__readout-label">Points</span><span class="sdi-calculator__readout-value" id="sdi-calc-points">0</span></div>
        <div><span class="sdi-calculator__readout-label">Current tier</span><span class="sdi-calculator__readout-value" id="sdi-calc-tier">Pre-tier</span></div>
      </div>
      <p class="sdi-calculator__note" id="sdi-calc-note">Refer members to begin building toward scholarship eligibility.</p>
    </div>
    <div class="sdi-calc-tiers"><div class="sdi-calc-tier" data-threshold="300" data-award="3000"><div class="sdi-calc-tier__row"><span>300 points</span><span class="sdi-calc-tier__award">$3,000</span></div><div class="sdi-calc-tier__track"><div class="sdi-calc-tier__fill"></div></div><p class="sdi-calc-tier__note">10 confirmed referrals</p></div><div class="sdi-calc-tier" data-threshold="600" data-award="6000"><div class="sdi-calc-tier__row"><span>600 points</span><span class="sdi-calc-tier__award">$6,000</span></div><div class="sdi-calc-tier__track"><div class="sdi-calc-tier__fill"></div></div><p class="sdi-calc-tier__note">20 confirmed referrals</p></div><div class="sdi-calc-tier" data-threshold="900" data-award="9000"><div class="sdi-calc-tier__row"><span>900 points</span><span class="sdi-calc-tier__award">$9,000</span></div><div class="sdi-calc-tier__track"><div class="sdi-calc-tier__fill"></div></div><p class="sdi-calc-tier__note">30 confirmed referrals</p></div><div class="sdi-calc-tier" data-threshold="1200" data-award="12000"><div class="sdi-calc-tier__row"><span>1200 points</span><span class="sdi-calc-tier__award">$12,000</span></div><div class="sdi-calc-tier__track"><div class="sdi-calc-tier__fill"></div></div><p class="sdi-calc-tier__note">40 referrals · top tier</p></div></div>
    <script>
    (function() {
      var input = document.getElementById('sdi-calc-input');
      var range = document.getElementById('sdi-calc-range');
      var pointsEl = document.getElementById('sdi-calc-points');
      var tierEl = document.getElementById('sdi-calc-tier');
      var noteEl = document.getElementById('sdi-calc-note');
      var tiers = document.querySelectorAll('.sdi-calc-tier');
      if (!input || !range) return;
      function update(count) {
        count = Math.max(0, Math.min(200, count));
        var points = count * 30;
        pointsEl.textContent = points.toLocaleString();
        var current = null, next = null;
        tiers.forEach(function(el) {
          var threshold = Number(el.getAttribute('data-threshold'));
          var fill = el.querySelector('.sdi-calc-tier__fill');
          var pct = Math.max(0, Math.min(100, Math.round((points / threshold) * 100)));
          fill.style.width = pct + '%';
          el.classList.toggle('is-reached', points >= threshold);
          if (points >= threshold) current = el;
          if (!next && points < threshold) next = el;
        });
        tierEl.textContent = current ? ('$' + Number(current.getAttribute('data-award')).toLocaleString()) : 'Pre-tier';
        if (next) {
          var toNext = Math.ceil((Number(next.getAttribute('data-threshold')) - points) / 30);
          noteEl.textContent = toNext + (toNext === 1 ? ' more confirmed referral reaches the ' : ' more confirmed referrals reach the ') + '$' + Number(next.getAttribute('data-award')).toLocaleString() + ' level.';
        } else {
          noteEl.textContent = 'You are at the top published tier. Further referrals continue to fund awards for other applicants.';
        }
      }
      input.addEventListener('input', function() { range.value = input.value; update(Number(input.value) || 0); });
      range.addEventListener('input', function() { input.value = range.value; update(Number(range.value) || 0); });
      update(0);
    })();
    </script>
    "}, "elements": [], "isInner": false, "widgetType": "html"}], "isInner": true}, {"id": "124836e", "elType": "widget", "settings": {"editor": "<p style='color:#97999D;font-size:0.82rem;'>Estimate only. Reaching a tier does not guarantee an award — scholarships are subject to program rules, verification, available funding and applicable law. Final terms are pending legal and charitable-solicitation review.</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}], "isInner": true}], "isInner": false}, {"id": "fd13fa8", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "_element_id": "community", "css_classes": "sdi-section sdi-section--light"}, "elements": [{"id": "d92dbab", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-container", "flex_direction": "column", "flex_gap": {"unit": "px", "size": 32, "column": "32", "row": "32"}}, "elements": [{"id": "cfcc137", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-grid sdi-grid--2", "flex_gap": {"unit": "px", "size": 48, "column": "48", "row": "48"}}, "elements": [{"id": "07a3e0d", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "flex_direction": "column", "flex_gap": {"unit": "px", "size": 14, "column": "14", "row": "14"}}, "elements": [{"id": "0f3450f", "elType": "widget", "settings": {"editor": "<p style='font-family:ui-monospace,Menlo,monospace;font-size:0.75rem;color:var(--sdi-color-silver);'>Program 05 · runs on this page</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}, {"id": "1af77cb", "elType": "widget", "settings": {"title": "Community Engagement", "header_size": "h2"}, "elements": [], "isInner": false, "widgetType": "heading"}, {"id": "1a4bcce", "elType": "widget", "settings": {"editor": "<p style='color:#2c3a51;max-width:52ch;'>Regional meetups, volunteer days and recipient spotlights — the part of membership that happens in person.</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}], "isInner": true}, {"id": "56fbbc4", "elType": "widget", "settings": {"html": "<div class="sdi-fact-grid"><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Purpose</p><p>Connect members in person, and let scholarship recipients meet the community that funded them.</p></div><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Eligibility</p><p>Open to all active members and their included dependents. Some volunteer days have host-site age requirements.</p></div><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Participation process</p><p>RSVP through the Member Portal. Seats are limited per event and released in the order RSVPs arrive.</p></div><div class="sdi-fact-cell"><p class="sdi-fact-cell__label">Applicable terms</p><p>Events are unpaid and voluntary; members cover their own travel. Photography consent is requested on site, never assumed.</p><a href="/legal/#terms" class="sdi-auth-link">Terms of Use</a></div></div>"}, "elements": [], "isInner": false, "widgetType": "html"}], "isInner": true}, {"id": "eef6df8", "elType": "widget", "settings": {"html": "<div class="sdi-grid sdi-grid--3" style="margin-top:38px;"><div class="sdi-event-card"><span class="sdi-event-card__tag">Regional meetup</span><h3>Austin, TX — trip planning night</h3><p class="sdi-event-card__meta">October 18, 2026 · 6:30 pm · East Sixth Street</p><p>An informal evening for members in Central Texas: shared itineraries, directory walkthrough, and a Q&amp;A with two local travel advisors.</p></div><div class="sdi-event-card"><span class="sdi-event-card__tag">Volunteer day</span><h3>Charlotte, NC — school supply drive</h3><p class="sdi-event-card__meta">November 7, 2026 · 9:00 am – 1:00 pm</p><p>Packing and distributing supplies with two partner schools near our Charlotte office. Ages 14 and up at the host site's request.</p></div><div class="sdi-event-card sdi-event-card--spotlight"><span class="sdi-event-card__tag sdi-event-card__tag--muted">Recipient spotlight</span><div class="sdi-event-card__avatar">photo</div><h3>Jasmine Cole</h3><p class="sdi-event-card__meta">$6,000 award · 2025 cohort</p><p class="sdi-pull-quote" style="margin:10px 0 0;font-size:1.05rem;">Twenty people I have never met paid for my second year.</p><a href="/scholarships/" class="sdi-auth-link">Read recipient stories</a></div></div>"}, "elements": [], "isInner": false, "widgetType": "html"}, {"id": "f92a1f7", "elType": "widget", "settings": {"editor": "<p style='color:#97999D;font-size:0.82rem;'>Event dates, locations and recipient stories are placeholders pending a confirmed schedule and consented stories.</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}], "isInner": true}], "isInner": false}, {"id": "3cb25c8", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-section sdi-section--light sdi-section--tinted"}, "elements": [{"id": "8c1ebc5", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-container", "flex_direction": "column", "flex_gap": {"unit": "px", "size": 32, "column": "32", "row": "32"}}, "elements": [{"id": "f67e20b", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-flex-between", "flex_gap": {"unit": "px", "size": 40, "column": "40", "row": "40"}}, "elements": [{"id": "293b0bc", "elType": "widget", "settings": {"title": "The three programs with their own pages", "header_size": "h2"}, "elements": [], "isInner": false, "widgetType": "heading"}, {"id": "3e12385", "elType": "widget", "settings": {"editor": "<p style='color:var(--sdi-color-text-secondary);max-width:50ch;'>Each has its own eligibility rules, forms and terms — summarized here, in full on its page.</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}], "isInner": true}, {"id": "3711cb7", "elType": "widget", "settings": {"html": "<div class="sdi-grid sdi-grid--3" style="margin-top:36px;"><div class="sdi-linked-program"><p class="sdi-numbered-card__number">Program 02</p><h3>Travel Purchase Fundraising</h3><p>Qualifying purchases made through our fintech partner contribute to the scholarship fund automatically, at no added cost to the member.</p><ul><li>Eligibility: active members, enrolled in the portal</li><li>Terms: partner disclosure on every listing</li></ul><a href="/fundraising/" class="sdi-auth-link" style="margin-top:auto;padding-top:22px;">Go to Fundraising</a></div><div class="sdi-linked-program"><p class="sdi-numbered-card__number">Program 03</p><h3>Retailer &amp; Restaurant Partnerships</h3><p>A $25 or $50 partner donation returns 20% savings on qualifying purchases, with minimum spend of $50 or $75 where applicable.</p><ul><li>Eligibility: open to members and partner businesses</li><li>Terms: offer conditions set per partner</li></ul><a href="/partnerships/" class="sdi-auth-link" style="margin-top:auto;padding-top:22px;">Go to Partnerships</a></div><div class="sdi-linked-program sdi-linked-program--gold"><p class="sdi-numbered-card__number">Program 04</p><h3>Academic Scholarship Program</h3><p>Four award levels from $3,000 to $12,000, tiered by referral points and awarded subject to available funding.</p><ul><li>Eligibility: verified students, application required</li><li>Terms: pending legal and tax review</li></ul><a href="/scholarships/" class="sdi-auth-link" style="margin-top:auto;padding-top:22px;">Go to Scholarships</a></div></div>"}, "elements": [], "isInner": false, "widgetType": "html"}], "isInner": true}], "isInner": false}, {"id": "a953f74", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-section sdi-section--light sdi-section--deep"}, "elements": [{"id": "64255c4", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-container", "flex_direction": "column", "flex_gap": {"unit": "px", "size": 32, "column": "32", "row": "32"}}, "elements": [{"id": "28719fd", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "css_classes": "sdi-flex-between", "flex_gap": {"unit": "px", "size": 40, "column": "40", "row": "40"}}, "elements": [{"id": "df27df6", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "flex_direction": "column", "flex_gap": {"unit": "px", "size": 10, "column": "10", "row": "10"}}, "elements": [{"id": "bb68580", "elType": "widget", "settings": {"title": "Programs open the moment your membership is active", "header_size": "h2"}, "elements": [], "isInner": false, "widgetType": "heading"}, {"id": "dae6200", "elType": "widget", "settings": {"editor": "<p style='color:#DCDEE3;max-width:52ch;'>Referral link, RSVPs and partner offers all live in the Member Portal.</p>"}, "elements": [], "isInner": false, "widgetType": "text-editor"}], "isInner": true}, {"id": "a29af16", "elType": "container", "settings": {"content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "